'use strict';

const { execFile, spawn } = require('child_process');
const { promisify } = require('util');
const {
  createInputFromAutoDetect
} = require('..');

const execFileAsync = promisify(execFile);

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const options = {
    mode: process.env.CLIPBOARD_COUNTDOWN_MODE || 'paste',
    seconds: Number(process.env.CLIPBOARD_COUNTDOWN_SECONDS || 5),
    portPath: process.env.THIFLOW_ROBOT_PORT || process.env.CH9329_PORT || process.env.NANOKVM_PORT || '',
    kind: process.env.THIFLOW_ROBOT_KIND || '',
    text: process.env.CLIPBOARD_COUNTDOWN_TEXT || `thiflow-robot paste test ${new Date().toISOString()}`,
    selectAll: process.env.CLIPBOARD_COUNTDOWN_SELECT_ALL === '1'
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];

    if (arg === '--mode' && next) {
      options.mode = next;
      index += 1;
    } else if ((arg === '--seconds' || arg === '-s') && next) {
      options.seconds = Number(next);
      index += 1;
    } else if (arg === '--port' && next) {
      options.portPath = next;
      index += 1;
    } else if (arg === '--kind' && next) {
      options.kind = next;
      index += 1;
    } else if (arg === '--text' && next) {
      options.text = next;
      index += 1;
    } else if (arg === '--select-all') {
      options.selectAll = true;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  if (!['paste', 'copy'].includes(options.mode)) {
    throw new Error('--mode must be paste or copy');
  }

  if (!Number.isFinite(options.seconds) || options.seconds < 0) {
    throw new Error('--seconds must be a non-negative number');
  }

  if (options.kind && !['nanokvm', 'ch9329'].includes(options.kind)) {
    throw new Error('--kind must be nanokvm or ch9329');
  }

  return options;
}

function printHelp() {
  console.log([
    'Usage:',
    '  node demos/clipboard-countdown.js --mode paste --port /dev/cu.usbserial-130 --kind ch9329 --text "hello"',
    '  node demos/clipboard-countdown.js --mode copy --port /dev/cu.usbserial-130 --kind ch9329',
    '',
    'Paste mode sets the macOS clipboard with pbcopy, counts down, then sends Cmd+V.',
    'Copy mode counts down, sends Cmd+C, then prints the macOS clipboard with pbpaste.'
  ].join('\n'));
}

async function setClipboard(text) {
  await new Promise((resolve, reject) => {
    const child = spawn('pbcopy');
    let stderr = '';

    child.stderr.on('data', (data) => {
      stderr += data.toString();
    });

    child.on('error', reject);
    child.on('close', (code) => {
      if (code === 0) {
        resolve();
        return;
      }
      reject(new Error(`pbcopy exited with code ${code}: ${stderr.trim()}`));
    });

    child.stdin.end(text);
  });
}

async function getClipboard() {
  const { stdout } = await execFileAsync('pbpaste');
  return stdout;
}

async function countdown(seconds, message) {
  const wholeSeconds = Math.floor(seconds);
  for (let remaining = wholeSeconds; remaining > 0; remaining -= 1) {
    console.log(`[clipboard-countdown] ${remaining}s 后${message}...`);
    await sleep(1000);
  }

  const extraMs = Math.round((seconds - wholeSeconds) * 1000);
  if (extraMs > 0) {
    await sleep(extraMs);
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    printHelp();
    return;
  }

  if (process.platform !== 'darwin') {
    throw new Error(`clipboard-countdown currently uses macOS pbcopy/pbpaste, got ${process.platform}`);
  }

  const { detection, input } = await createInputFromAutoDetect({
    portPath: options.portPath || undefined,
    kind: options.kind || undefined
  });

  await input.connect();
  console.log(`[clipboard-countdown] 已连接: ${detection.kind || 'unknown'} ${detection.portPath}`);

  try {
    if (options.mode === 'paste') {
      await setClipboard(options.text);
      console.log(`[clipboard-countdown] 已写入 macOS 剪贴板: ${JSON.stringify(options.text)}`);
      const clipboardBeforePaste = await getClipboard();
      if (clipboardBeforePaste !== options.text) {
        throw new Error(
          `pbcopy self-check failed: expected ${JSON.stringify(options.text)}, got ${JSON.stringify(clipboardBeforePaste)}`
        );
      }
      console.log('[clipboard-countdown] pbpaste 自检通过');
      await countdown(options.seconds, '发送 Cmd+V，请聚焦目标输入框');
      if (options.selectAll) {
        await input.keyTap('a', ['command']);
        await input.keyToggle('command', 'up');
        await sleep(150);
      }
      await input.pasteShortcut('darwin');
      console.log('[clipboard-countdown] Cmd+V 已发送');
      return;
    }

    await countdown(options.seconds, '发送 Cmd+C，请先选中目标文本');
    await input.keyTap('c', ['command']);
    await input.keyToggle('command', 'up');
    await sleep(300);
    const copied = await getClipboard();
    console.log(`[clipboard-countdown] pbpaste 读到: ${JSON.stringify(copied)}`);
  } finally {
    await input.disconnect().catch(() => {});
  }
}

main().catch((error) => {
  console.error('[clipboard-countdown] failed:', error);
  process.exitCode = 1;
});
